const LOGO_URL=window.AIS_LOGO || './standards_logo.png';
document.querySelector('.loading-logo')?.setAttribute('src',LOGO_URL);
const PROJECT_NAME=String(window.AIS_CONFIG?.projectName || 'Agrivoltaics International Standards');
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true">${ICONS[name]||ICONS.info}</svg>`;
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=value=>value===null || value===undefined ? '—' : `${Math.round(value*100)}%`;
const selectedAttr=(a,b)=>a===b?' selected':'';
const checkedAttr=value=>value?' checked':'';
const labelCategory=name=>name==='System Specifications'?'PV systems':name==='Metadata'?'Site & study context':name;
const option=(value,label,current)=>`<option value="${esc(value)}"${selectedAttr(value,current)}>${esc(label)}</option>`;
const badge=v=>{const key=typeof v==='string'?v:tierKey(v),t=TIERS[key];return `<span class="badge ${t.tone}" title="${esc(t.label)}"><span class="badge-code">${key==='R'?'?':key}</span>${esc(t.short)}</span>`;};
const statusLabel=value=>({'planned':'Planned','collected':'Collected','not-collected':'Not collected','not-applicable':'Not applicable'}[value]||value);
const app=document.getElementById('app');
const detailDialog=document.getElementById('detail-dialog');
const utilityDialog=document.getElementById('utility-dialog');
let DATA,byId,expertById,storeKey,storageAvailable=true,hasSavedStudy=false,toastTimer,detailId=null,detailTab='overview',confirmAction=null,pendingImport=null,feedbackVariable=null;
const state={view:'setup',context:structuredClone(DEFAULT_CONTEXT),study:{name:'',notes:''},plan:{},allLibrary:false,
  filters:{query:'',category:'',subcategory:'',tier:'',units:'',evidence:''},sort:'priority',page:1,pageSize:25,mobileFilters:false,planGrouping:'priority'};
const countPlan=()=>Object.keys(state.plan).length;
function toast(message,error=false){const el=document.getElementById('toast');el.textContent=message;el.className=`toast show${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),error?7500:4000);}
function save(){
  try{localStorage.setItem(storeKey,JSON.stringify(exportPlan(state,DATA)));storageAvailable=true;hasSavedStudy=true;}
  catch{if(storageAvailable) toast('Browser storage is unavailable. Export JSON to keep your plan.',true);storageAvailable=false;}
}
function setView(view,{all}={}){
  if(!['setup','library','plan','guide'].includes(view))view='setup';
  state.view=view;
  if(view==='library' && all!==undefined)state.allLibrary=all;
  if(view==='library' && !state.context.topics.length && all===undefined)state.allLibrary=true;
  if(detailDialog.open)detailDialog.close();
  history.replaceState(null,'',`#${view}`);
  render();window.scrollTo({top:0,behavior:'instant'});
  requestAnimationFrame(()=>document.querySelector('#main-content h1')?.focus({preventScroll:true}));
}
function navLink(view,label){return `<button class="nav-link${state.view===view?' active':''}" data-action="view" data-view="${view}" ${state.view===view?'aria-current="page"':''}>${label}${view==='plan'?`<span class="nav-count">${countPlan()}</span>`:''}</button>`;}
function header(){return `<header class="topbar"><div class="topbar-inner"><button class="brand" data-action="view" data-view="setup" aria-label="${esc(PROJECT_NAME)} home"><img class="brand-logo" src="${esc(LOGO_URL)}" alt="" width="36" height="36"><span class="brand-name">${esc(PROJECT_NAME)}</span></button><nav class="main-nav" aria-label="Main navigation">${navLink('setup','Study planner')}${navLink('library','Variable library')}${navLink('plan','My plan')}${navLink('guide','Classification guide')}</nav><div class="topbar-actions"><button class="feedback-button" data-action="feedback">${icon('chat')}<span>Feedback</span><span class="sr-only">Send feedback</span></button></div></div></header>`;}
function footer(){return `<footer class="app-footer"><span class="footer-source">${icon('book')}<span>Expert Matrix v15 · “All Variables” · 641 source variables<br>Demonstration dataset. Source units and classifications require scientific review.</span></span><div class="footer-actions"><button class="text-button" data-action="view" data-view="guide">Data & methodology</button><button class="text-button" data-action="privacy">Privacy</button><span class="save-status">${icon(storageAvailable?'check':'alert')}${storageAvailable?(hasSavedStudy?'Plan saved in this browser':'New plan · not yet saved'):'Export JSON to save your plan'}</span></div></footer>`;}
function steps(active){const items=['Define your study','Choose variables','Review & export'];return `<nav class="steps no-print" aria-label="Planning steps">${items.map((label,i)=>`<button class="step${active===i?' active':active>i?' done':''}" data-action="step" data-step="${i}"${active===i?' aria-current="step"':''}><span class="step-number">${active>i?icon('check'):String(i+1).padStart(2,'0')}</span><span>${label}</span>${i<2?icon('chevron','step-arrow'):''}</button>`).join('')}</nav>`;}
function scopeCount(){return scopedVariables(DATA.variables,state.context).length;}
function contextLine(){const names=TOPICS.filter(t=>state.context.topics.includes(t.id)).map(t=>t.name);return `<div class="context-line">${icon('filter')}${names.length?names.slice(0,3).map(n=>`<span class="context-pill">${esc(n)}</span>`).join(''):'<span>Required metadata and core variables</span>'}${names.length>3?`<span class="context-pill">+${names.length-3} topics</span>`:''}${state.context.cropGroups.length?`<span class="context-pill">${state.context.cropGroups.length} crop group${state.context.cropGroups.length>1?'s':''}</span>`:''}<button class="text-button" data-action="view" data-view="setup">Edit study</button></div>`;}
function setupView(){
  const c=state.context;
  return `<h1 class="sr-only" tabindex="-1">Study planner</h1>
    ${steps(0)}
    <div class="setup-main">
      <section class="panel panel-pad"><div class="section-heading"><div><h2>What are you studying?</h2><p>Select additional research focuses. Site and PV metadata are always included.</p></div><span class="section-number">01</span></div>
        <div class="topic-grid" aria-label="Research focus">${TOPICS.map(t=>`<button class="topic-card${c.topics.includes(t.id)?' selected':''}" data-action="topic" data-id="${t.id}" aria-pressed="${c.topics.includes(t.id)}"><span class="topic-icon">${icon(t.icon)}</span><span><strong>${t.name}</strong><small>${t.detail}</small></span><span class="choice-dot">${c.topics.includes(t.id)?icon('check'):''}</span></button>`).join('')}</div>
      </section>
      <section class="panel panel-pad"><div class="section-heading"><div><h2>Which crop groups are included?</h2><p>Optional. Select all that apply.</p></div><span class="section-number">02</span></div>
        <div class="chip-group">${CROP_GROUPS.map(g=>`<button class="crop-chip${c.cropGroups.includes(g)?' selected':''}" data-action="crop" data-group="${esc(g)}" aria-pressed="${c.cropGroups.includes(g)}">${c.cropGroups.includes(g)?icon('check'):icon('plus')}${esc(g)}</button>`).join('')}</div>
        <p class="helper">${icon('info')}<span>Group matches use workbook session coverage, not exclusive crop applicability. No selection keeps all crop groups.</span></p>
      </section>
      <section class="panel panel-pad"><details open><summary class="details-summary">Study details <span class="muted small">${icon('down')}</span></summary><div class="details-content"><div class="form-grid">
        <label class="field full">Study or experiment name<input id="study-name" data-study="name" value="${esc(state.study.name)}" maxlength="200" placeholder="e.g. Field crop shading experiment"></label>
        <div class="field full"><span>I am…</span><div class="mode-control" aria-label="Research stage"><button data-action="mode" data-mode="design" class="${c.mode==='design'?'active':''}" aria-pressed="${c.mode==='design'}">Designing an experiment</button><button data-action="mode" data-mode="report" class="${c.mode==='report'?'active':''}" aria-pressed="${c.mode==='report'}">Reporting an existing study</button></div><small>Sets the initial collection status for variables you add next.</small></div>
        <label class="field">PV arrangement<select id="configuration" data-context="configuration">${option('unspecified','Not specified / compare all',c.configuration)}${option('fixed','Fixed tilt',c.configuration)}${option('single-axis','Single-axis tracking',c.configuration)}${option('dual-axis','Dual-axis tracking',c.configuration)}${option('vertical','Vertical',c.configuration)}</select></label>
        <label class="field">Cell-level module geometry<select id="cell-geometry" data-context="cellGeometry">${option('unspecified','Keep available',c.cellGeometry)}${option('include','Relevant to this study',c.cellGeometry)}${option('exclude','Not relevant to this study',c.cellGeometry)}</select></label>
      </div><p class="helper">${icon('info')}<span>Required PV specifications stay in your plan. Mark tracking or cell-geometry fields “Not applicable” when they do not apply.</span></p></div></details></section>
      <div class="setup-actions"><button class="btn btn-primary" data-action="continue">Choose variables ${icon('arrow')}</button></div>
    </div>
    <p class="setup-footnote">Use this planner as a starting point, not a complete experimental protocol. The matrix’s original units are retained; missing units and unresolved classifications are explicitly flagged.</p>`;
}
function libraryScope(){return scopedVariables(DATA.variables,state.context,state.allLibrary);}
function visibleLibrary(){return sortVariables(filterVariables(libraryScope(),state.filters),state.sort);}
function priorityStrip(variables){const s=summarize(variables);return `<div class="priority-strip" aria-label="Priority filters">${['CD','CU','E','S'].map(code=>`<button class="priority-card ${TIERS[code].tone}${state.filters.tier===code?' active':''}" data-action="tier" data-tier="${code}" aria-pressed="${state.filters.tier===code}"><span><span class="priority-card-label"><span class="code-mark">${code}</span>${TIERS[code].short}</span><small>${code==='CD'?'Describe the study':code==='CU'?'Enable comparison':code==='E'?'Add scientific depth':'Explore specialized questions'}</small></span><strong>${s.tiers[code]}</strong></button>`).join('')}</div><div class="review-line">${icon('alert')}<button class="text-button" data-action="tier" data-tier="review">${s.review} need classification review</button><span>including ${s.tiers.C} legacy C ratings</span><span class="right-note">Unique ≥50% vote · NA excluded · no forced assignments</span></div>`;}
function filterPanel(base){
  const cats=Object.fromEntries(CATEGORY_ORDER.map(c=>[c,base.filter(v=>v.category===c).length]));
  const subs=[...new Set(base.filter(v=>!state.filters.category||v.category===state.filters.category).map(v=>v.subcategory))].sort((a,b)=>a.localeCompare(b));
  return `<aside class="panel filter-panel${state.mobileFilters?' open':''}" aria-label="Variable filters"><button class="filter-mobile-heading" style="width:100%;background:none;border:0;padding:0" data-action="mobile-filters" aria-expanded="${state.mobileFilters}">${icon('filter')} Filter variables ${icon('down')}</button><div class="filter-body"><div class="filter-title">Refine your shortlist<button class="text-button" data-action="reset-filters">Reset</button></div><div class="filter-label">Research domain</div><button class="category-filter${!state.filters.category?' active':''}" data-action="category" data-category="">All domains<span class="filter-count">${base.length}</span></button>${CATEGORY_ORDER.map(cat=>`<button class="category-filter${state.filters.category===cat?' active':''}" data-action="category" data-category="${esc(cat)}">${esc(labelCategory(cat))}<span class="filter-count">${cats[cat]}</span></button>`).join('')}
      <label class="field">Subcategory<select id="subcategory-filter" data-filter="subcategory">${option('','All subcategories',state.filters.subcategory)}${subs.map(s=>option(s,s,state.filters.subcategory)).join('')}</select></label>
      <label class="field">Priority / review status<select id="tier-filter" data-filter="tier">${option('','All priorities',state.filters.tier)}${['CD','CU','C','E','S','R'].map(k=>option(k,`${k==='R'?'?':k} · ${TIERS[k].short}`,state.filters.tier)).join('')}${option('review','All classification reviews',state.filters.tier)}</select></label>
      <label class="field">Units / reporting format<select id="units-filter" data-filter="units">${option('','Any unit status',state.filters.units)}${option('provided','Provided, no flagged issue',state.filters.units)}${option('missing','Not specified / TBD',state.filters.units)}${option('review','Needs a unit decision',state.filters.units)}</select></label>
      <label class="field">Expert evidence<select id="evidence-filter" data-filter="evidence">${option('','Any number of ratings',state.filters.evidence)}${option('3plus','At least 3 non-NA cells',state.filters.evidence)}${option('limited','Only 1–2 non-NA cells',state.filters.evidence)}${option('ambiguous','Includes unresolved entries',state.filters.evidence)}</select></label>
      ${!state.allLibrary?`<label class="foundation-toggle"><input type="checkbox" id="library-foundation" data-context="foundation"${checkedAttr(state.context.foundation)}><span>Include the starter checklist</span></label>`:''}
      <div class="filter-rule"><p>The four categories are unchanged by topic or crop-group filtering.</p><button class="btn btn-soft btn-sm" data-action="add-foundation">${icon('plus')}Add starter checklist</button></div></div></aside>`;
}
function activeFilters(){return `<div class="active-filters">${Object.entries(state.filters).filter(([k,v])=>v&&k!=='query').map(([key,value])=>`<button class="filter-chip" data-action="clear-filter" data-filter="${key}">${esc(key==='tier'?value==='review'?'Classification review':TIERS[value]?.short||value:value)}${icon('close')}<span class="sr-only">Remove filter</span></button>`).join('')}</div>`;}
function unitCell(v,entry=null){const custom=entry?.unitOverride?.trim();return `${custom?`<span class="unit-value">${esc(custom)}</span><span class="unit-flag">Researcher-entered</span>`:v.units.status==='provided'?`<span class="unit-value">${esc(v.units.display)}</span>${v.units.notes.length?`<span class="unit-flag">${icon('alert')}Check source units</span>`:''}`:`<span class="unit-missing">${esc(v.units.display)}</span>`}`;}
function variableRows(vars){return vars.map(v=>{const c=v.consensus;return `<tr class="${state.plan[v.id]?'selected':''}"><td class="check-col"><input class="check-input" type="checkbox" data-action="toggle-variable" data-id="${v.id}" aria-label="Include ${esc(v.name)} in plan"${checkedAttr(state.plan[v.id])}${isRequiredVariable(v)?' disabled title="Required metadata"':''}></td><td><button class="variable-name" data-action="detail" data-id="${v.id}">${esc(v.name)}</button><div class="variable-context"><span>${esc(labelCategory(v.category))}</span><span class="dot">·</span><span>${esc(v.subcategory)}</span>${isRequiredVariable(v)?'<span class="required-mark">Required</span>':''}${v.foundation?`<span class="foundation-mark" title="Editorial starter suggestion; not a vote-based classification">${icon('sprout')}Starter</span>`:''}</div></td><td>${unitCell(v)}</td><td>${badge(v)}<button class="vote-sub" data-action="detail" data-id="${v.id}" data-tab="votes" title="View all expert-session votes">${c.majorityCode?`${pct(c.agreement)} agreement`:(c.status==='tie'?'50/50 tie':c.status==='no-votes'?'No ratings':'No unique majority')}${c.denominator?` · n=${c.denominator}`:''}</button></td><td class="action-col"><button class="icon-button" data-action="detail" data-id="${v.id}" aria-label="Details for ${esc(v.name)}">${icon('chevron')}</button></td></tr>`;}).join('');}
function libraryView(){
  const base=libraryScope(),filtered=visibleLibrary(),maxPage=Math.max(1,Math.ceil(filtered.length/state.pageSize));state.page=Math.min(state.page,maxPage);
  const start=(state.page-1)*state.pageSize,end=Math.min(start+state.pageSize,filtered.length),pageVars=filtered.slice(start,end),allSelected=pageVars.length>0&&pageVars.every(v=>state.plan[v.id]);
  const selectedVisible=filtered.filter(v=>state.plan[v.id]).length;
  return `<section class="hero library-hero"><div><h1 tabindex="-1">Variable library</h1>${contextLine()}</div><div class="hero-right"><button class="btn btn-primary" data-action="view" data-view="plan">Review my plan <span class="nav-count">${countPlan()}</span>${icon('arrow')}</button></div></section>${steps(1)}${priorityStrip(base)}
    <div class="library-grid">${filterPanel(base)}<section aria-label="Variable results"><div class="scope-toggle" aria-label="Library scope"><button data-action="scope" data-scope="study" class="${!state.allLibrary?'active':''}" aria-pressed="${!state.allLibrary}">My study shortlist <span class="count">${scopeCount()}</span></button><button data-action="scope" data-scope="all" class="${state.allLibrary?'active':''}" aria-pressed="${state.allLibrary}">Full library <span class="count">641</span></button></div>
      <div class="list-toolbar"><label class="search-field">${icon('search')}<input id="variable-search" type="search" value="${esc(state.filters.query)}" placeholder="Search variables, topics, or units…" aria-label="Search variables" autocomplete="off"><kbd aria-hidden="true">/</kbd></label><label class="sr-only" for="sort-select">Sort variables</label><select class="sort-select" id="sort-select">${option('priority','Priority, then agreement',state.sort)}${option('name','Variable name A–Z',state.sort)}${option('votes','Most expert ratings',state.sort)}${option('agreement','Highest agreement',state.sort)}</select></div>
      ${activeFilters()}<div class="result-bar"><span><strong>${filtered.length}</strong> variables${selectedVisible?` · ${selectedVisible} in your plan`:''}</span><div class="result-actions"><button class="text-button" data-action="add-core">Add CD + CU</button><button class="btn btn-soft btn-sm" data-action="add-filtered"${filtered.length?'':' disabled'}>${icon('plus')}Add filtered (${filtered.length})</button></div></div>
      ${filtered.length?`<div class="table-wrap"><table class="variable-table"><caption class="sr-only">Research variables, source units, and expert-vote classifications. Use a variable name to view evidence and planning fields.</caption><colgroup><col class="check-col"><col class="name-col"><col class="units-col"><col class="tier-col"><col class="action-col"></colgroup><thead><tr><th class="check-col"><input id="page-select" class="check-input" type="checkbox" data-action="select-page" aria-label="Select or remove the ${pageVars.length} variables on this page"${checkedAttr(allSelected)}></th><th scope="col">Variable</th><th scope="col">Unit / format</th><th scope="col">Priority & evidence</th><th class="action-col"><span class="sr-only">Details</span></th></tr></thead><tbody>${variableRows(pageVars)}</tbody></table></div><div class="pagination"><div>Showing ${start+1}–${end} of ${filtered.length}<label> <span class="sr-only">Results per page</span><select id="page-size">${[25,50,100].map(n=>option(n,`${n} / page`,state.pageSize)).join('')}</select></label></div><div class="page-controls"><button class="btn btn-sm" data-action="page" data-delta="-1"${state.page===1?' disabled':''} aria-label="Previous page">${icon('left')}</button><span>Page ${state.page} of ${maxPage}</span><button class="btn btn-sm" data-action="page" data-delta="1"${state.page===maxPage?' disabled':''} aria-label="Next page">${icon('chevron')}</button></div></div>`:`<div class="empty-state"><div class="empty-icon">${icon('search')}</div><h2>No matching variables.</h2><p>Try a broader term, remove a filter, or switch to the full library. Your selected variables are still in your plan.</p><button class="btn btn-soft" data-action="reset-filters">Clear filters</button></div>`}
      <div class="selection-dock"><div class="dock-count"><strong>${countPlan()}</strong><span>variables in your plan<small>Selections stay with you as you explore.</small></span></div><button class="btn" data-action="view" data-view="plan">Review & export ${icon('arrow')}</button></div>
    </section></div>`;
}
function selectedVariables(){return sortVariables(DATA.variables.filter(v=>state.plan[v.id]));}
function missingCore(){return DATA.variables.filter(v=>['CD','CU'].includes(v.consensus.category)&&conditionMatches(v,state.context)&&!state.plan[v.id]);}
function planTable(vars){return `<div class="table-wrap"><table class="variable-table plan-table"><caption class="sr-only">Selected variables and your collection status. Open a variable to add sampling details.</caption><colgroup><col class="name-col"><col class="units-col"><col class="tier-col"><col class="action-col"></colgroup><thead><tr><th>Variable</th><th>Reporting unit / format</th><th>Collection status</th><th class="action-col"><span class="sr-only">Remove</span></th></tr></thead><tbody>${vars.map(v=>`<tr><td><button class="variable-name" data-action="detail" data-id="${v.id}">${esc(v.name)}</button><div class="variable-context">${esc(labelCategory(v.category))} · ${esc(v.subcategory)}</div>${state.plan[v.id].method||state.plan[v.id].schedule?'<div class="variable-context">Planning details added</div>':''}</td><td>${unitCell(v,state.plan[v.id])}</td><td><select class="status-select" data-plan-status="${v.id}" aria-label="Collection status for ${esc(v.name)}">${COLLECTION_STATUSES.map(s=>option(s,statusLabel(s),state.plan[v.id].status)).join('')}</select></td><td class="action-col no-print">${isRequiredVariable(v)?'<span class="required-mark" title="Required metadata">Required</span>':`<button class="icon-button" data-action="remove-variable" data-id="${v.id}" aria-label="Remove ${esc(v.name)}">${icon('trash')}</button>`}</td></tr>`).join('')}</tbody></table></div>`;}
function printDetails(vars){return `<section class="print-only"><h2 class="print-title">Sampling and reporting details</h2>${vars.map(v=>{const e=state.plan[v.id];return `<div class="print-detail"><strong>${esc(v.name)}</strong> · ${esc(v.id)}<br>Source classification: ${esc(v.consensus.category||STATUS_NAMES[v.consensus.status])}; ${v.consensus.denominator} non-NA cells; agreement ${pct(v.consensus.agreement)}.<br>Source unit: ${esc(v.units.raw||'Not specified')}. Reporting unit: ${esc(reportingUnit(v,e)||'Unresolved')}.${v.units.needsReview?` Source unit review: ${esc(v.units.notes.join(' ')||'No reporting format recorded.')}`:''}<br>Schedule: ${esc(e.schedule||'Not recorded')}. Position: ${esc(e.position||'Not recorded')}. Method: ${esc(e.method||'Not recorded')}.<br>Notes: ${esc(e.notes||'None')}.</div>`;}).join('')}</section>`;}
function planView(){
  const vars=selectedVariables(),s=summarize(vars),missing=missingCore(),unitDecisions=vars.filter(v=>v.units.needsReview&&!state.plan[v.id].unitOverride.trim()).length;
  const groups=state.planGrouping==='priority'?Object.keys(TIERS).map(k=>({key:k,label:badge(k),items:vars.filter(v=>tierKey(v)===k)})):CATEGORY_ORDER.map(k=>({key:k,label:`<h3>${esc(labelCategory(k))}</h3>`,items:vars.filter(v=>v.category===k)}));
  return `<section class="hero plan-hero"><div><h1 tabindex="-1">My plan</h1><p>Review your selections, add reporting details, and take your plan with you.</p></div><div class="hero-right"><button class="btn" data-action="import">${icon('upload')}Import plan</button><button class="btn btn-soft" data-action="view" data-view="library">${icon('plus')}Add variables</button></div></section>${steps(2)}
    ${vars.length?`<div class="plan-stats"><div class="panel plan-stat"><span class="stat-icon">${icon('checklist')}</span><strong>${vars.length}</strong><span>selected<br>variables</span></div><div class="panel plan-stat"><span class="stat-icon warning">${icon('alert')}</span><strong>${unitDecisions}</strong><span>unit / format<br>decisions</span></div><div class="panel plan-stat"><strong>${s.review}</strong><span>classification<br>reviews</span></div><div class="panel plan-stat"><strong>${missing.length}</strong><span>CD / CU variables<br>not in this plan</span></div></div>
    <div class="plan-layout"><div class="plan-main"><section class="panel panel-pad"><div class="form-grid"><label class="field full">Study name<input id="plan-study-name" data-study="name" maxlength="200" value="${esc(state.study.name)}" placeholder="Name your measurement plan"></label><label class="field full">Study notes & deviations<textarea id="study-notes" data-study="notes" maxlength="8000" rows="3" placeholder="Record reference treatments, replication, scope limitations, or reasons for omitting core variables.">${esc(state.study.notes)}</textarea></label></div>${contextLine()}<p class="plan-report-info">Stage: ${state.context.mode==='report'?'reporting an existing study':'designing an experiment'}. Collection status is researcher-entered, not verified by the tool.</p></section>
      ${missing.length?`<details class="review-check no-print"><summary><span>${icon('info')} ${missing.length} expert-voted CD / CU variables are not selected</span>${icon('down')}</summary><p>These are the matrix’s exact CD / CU decisions, not a claim that every field fits every experiment. Add relevant variables or document omissions in your study notes.</p><ul class="missing-list">${missing.map(v=>`<li>${badge(v)} <button class="text-button" data-action="detail" data-id="${v.id}">${esc(v.name)}</button></li>`).join('')}</ul><button class="btn btn-soft btn-sm" data-action="add-missing-core">${icon('plus')}Add missing CD + CU</button></details>`:''}
      <section><div class="plan-actions no-print"><p>Open a variable to set units, sampling, and methods.</p><label class="field"><span class="sr-only">Group plan by</span><select id="plan-grouping">${option('priority','Group by priority',state.planGrouping)}${option('category','Group by domain',state.planGrouping)}</select></label></div>${groups.filter(g=>g.items.length).map(g=>`<div class="plan-group-heading">${g.label}<span class="count">${g.items.length} variable${g.items.length===1?'':'s'}</span></div>${planTable(g.items)}`).join('')}</section>${printDetails(vars)}</div>
      <aside class="panel export-panel"><h2>Export plan</h2><p>Export a working checklist, a reusable plan, or a blank observation template.</p><button class="btn btn-primary" data-action="export-csv">${icon('download')}Measurement plan · CSV${icon('arrow')}</button><button class="btn" data-action="export-json">${icon('file')}Save & share plan · JSON</button><button class="btn" data-action="export-template">${icon('grid')}Observation template · CSV</button><button class="btn" data-action="print">${icon('print')}Print plan</button><div class="export-divider"></div><div class="export-note"><p class="small"><strong>Draft, not a validated protocol.</strong><br>${unitDecisions} unit decisions and ${s.review} classification reviews remain. Exports retain the original source values and review flags.</p><p class="small">The observation template has one blank row per variable. Duplicate rows for repeated observations; do not treat different units as interchangeable.</p></div><button class="btn btn-quiet" data-action="export-audit">${icon('download')}Full classification audit</button><button class="btn btn-quiet btn-danger" data-action="clear-plan">${icon('trash')}Clear optional variables</button></aside></div>`:
    `<div class="empty-state"><div class="empty-icon">${icon('checklist')}</div><h2>Your plan starts with a variable.</h2><p>Add variables from the library, use the starter checklist, or import a previously saved JSON plan.</p><button class="btn btn-primary" data-action="view" data-view="library">Explore variables ${icon('arrow')}</button> <button class="btn" data-action="import">${icon('upload')}Import plan</button></div>`}`;
}
function guideView(){const s=DATA.stats;return `<section class="hero guide-hero"><div><h1 tabindex="-1">Classification guide</h1><p>Four target categories. Original source units. Every classification traceable to its votes.</p></div><div class="hero-right"><button class="btn" data-action="export-audit">${icon('download')}Download audit</button></div></section>
  <div class="guide-notice"><strong>Legacy C is not the same as CU.</strong> The source includes ${s.classifications['legacy-core']} majority-C decisions without a descriptive / universal subtype. They remain visible as “Core · review.” Ties, below-threshold votes, and unrated variables are also review states—not extra scientific categories.</div>
  <div class="guide-grid"><article class="panel guide-card">${badge('CD')}<h2>Core / Descriptive</h2><p>Required descriptive metadata for each research installation. These characterize the site, agrivoltaic and agricultural systems, experimental design, and management context rather than measured responses.</p><p class="examples"><strong>Framework examples</strong>Location, climate classification, module technology, system geometry, cultivar, planting density, reference treatment, and experimental layout.</p></article><article class="panel guide-card">${badge('CU')}<h2>Core / Universal</h2><p>Basic microclimate, soil, and energy measurements required at each installation to enable comparison between agrivoltaic systems and their reference treatments.</p><p class="examples"><strong>Framework examples</strong>Air temperature, relative humidity, precipitation, wind speed, solar radiation / PAR, soil temperature, soil moisture, and PV energy production.</p></article><article class="panel guide-card">${badge('E')}<h2>Enhanced</h2><p>High scientific value and strongly encouraged, but cost, infrastructure, spatial replication, or measurement burden prevents universal collection.</p><p class="examples"><strong>Framework examples</strong>Spatial PAR arrays, multi-depth soil moisture, leaf and canopy temperature, detailed soil-water balance, and power-quality data.</p></article><article class="panel guide-card">${badge('S')}<h2>Supplemental</h2><p>Specialized, emerging, expensive, or not yet sufficiently standardized measurements that extend the scientific value of a site.</p><p class="examples"><strong>Framework examples</strong>Hyperspectral imaging, eddy covariance, metabolomics, eDNA, advanced plant physiology, and high-resolution thermal imaging.</p></article></div>
  <div class="guide-split"><section class="panel panel-pad guide-section"><h2>How the votes become a category</h2><p>Each of the 90 expert-by-session columns contributes at most one indication per variable. NA, N/A, and blank cells are excluded. Expert-session cells are not assumed to be 90 unique people.</p><div class="formula">support for one code / all non-NA cells ≥ 0.50<br>AND exactly one code reaches the threshold</div><h3>Uncertain entries stay uncertain</h3><p>Codes are case-normalized. “C = Core” counts as C and “E*” as E, with the original literal retained. Mixed codes, conflicts such as “C | E”, conditional entries, and unknown marks remain in the denominator but give no category a vote. This conservative rule does not double-count a cell.</p><h3>Exactly 50% is accepted—unless it is tied</h3><p>A unique 50% category is assigned. A 50/50 split is not arbitrarily resolved. If C wins, no CD / CU subtype is invented. If all cells are NA, the variable is unrated. A one-cell majority is shown but marked as limited evidence; the “1–2” flag is an editorial caution, not an exclusion rule.</p><h3>Rankings are not re-voted by your filters</h3><p>Sort order is CD, CU, legacy C, E, S, then other review states. Within a tier, agreement and response count come first. The placement of legacy C is a navigation choice, not evidence of universal applicability. Topic and crop filters change relevance, not the global classification.</p></section>
    <section class="panel panel-pad guide-section"><h2>The matrix at a glance</h2><table class="audit-table"><tbody>${[['Source variables',641],['Expert-session columns',90],['Core / Descriptive · CD',s.classifications.CD],['Core / Universal · CU',s.classifications.CU],['Enhanced · E',s.classifications.E],['Supplemental · S',s.classifications.S],['Legacy C · subtype pending',s.classifications['legacy-core']],['No unique majority below 50%',s.classifications['no-consensus']],['50/50 ties',s.classifications.tie],['No ratings',s.classifications['no-votes']],['Unit / format not recorded',s.units.missing],['Unit / format marked TBD',s.units.tbd]].map(([label,value])=>`<tr><th scope="row">${esc(label)}</th><td>${value}</td></tr>`).join('')}</tbody></table><div class="source-box"><strong>Source</strong><br>${esc(DATA.source.file)}<br>First worksheet: ${esc(DATA.source.sheet)}<br>Import date: ${DATA.importDate}<br>Policy: ${esc(DATA.policyVersion)}<br><span class="mono">SHA-256: ${DATA.source.sha256}</span></div><div class="guide-actions"><button class="btn btn-sm" data-action="export-audit">${icon('download')}Audit CSV</button><button class="btn btn-sm" data-action="export-data">${icon('download')}Source data JSON</button></div></section></div>
  <section class="panel panel-pad guide-section"><h2>Relevance, units, and scientific review</h2><h3>Start with the framework; keep the evidence separate</h3><p>The starter checklist is an editorial selection of existing variables based on the supplied framework. It is not a new expert vote, a validated minimum protocol, or an exhaustive metadata standard. All 26 exact CD / CU variables are selected in new plans and can be removed with a documented omission. Required site, study-design and PV metadata cannot be removed, including through bulk actions or imports. Requirements do not alter source votes. Conditional specifications remain in the plan; mark them Not applicable and explain why in the variable notes. Crop-group filtering uses the source session coverage only for crop-domain matching; it does not establish that a variable is unsuitable for any other crop. Configuration filters are explicit relevance rules, never classification rules.</p><h3>Units are preserved, not certified</h3><p>The library displays the workbook’s “Units / Classification” field without numerical conversion. NA does not establish whether a field is dimensionless, categorical, or missing a physical unit. TBD stays unresolved. Possible quantity mismatches and ambiguous conventions are flagged. Enter a study-specific unit or format in your plan; it is exported separately as researcher-entered and never overwrites the source.</p><h3>Methods and publications are ready for curation</h3><p>Imported methodology notes are shown as source notes, not independently validated protocols. Each variable has structured method and publication fields for future reviewed additions. No placeholder citations or invented links are presented. Contributor feedback can target a variable’s stable identifier and source row.</p><h3>Original records remain intact</h3><p>All 641 variables are retained. A small display-only subcategory cleanup fixes case variants and obvious spelling errors; the original subcategory remains in every record and export. No variables, fresh/dry bases, tissue distinctions, depths, or time periods have been merged. Public vote evidence uses anonymous expert-session IDs instead of expert initials. The original workbook is not included in the public site.</p></section>`;}
function render({preserveFocus=true}={}){
  const focused=preserveFocus&&app.contains(document.activeElement)?document.activeElement:null;
  const id=focused?.id,selectionStart=focused?.selectionStart,selectionEnd=focused?.selectionEnd;
  const focusSelector=focused ? (id ? '#'+CSS.escape(id) : Object.keys(focused.dataset||{}).length ? focused.tagName.toLowerCase()+Object.entries(focused.dataset).map(([k,v])=>'[data-'+k.replace(/[A-Z]/g,c=>'-'+c.toLowerCase())+'="'+CSS.escape(v)+'"]').join('') : null) : null;
  app.innerHTML=header()+`<main id="main-content" class="shell">${state.view==='setup'?setupView():state.view==='library'?libraryView():state.view==='plan'?planView():guideView()}${footer()}</main>`;
  if(state.view==='library'){
    const pageVars=visibleLibrary().slice((state.page-1)*state.pageSize,state.page*state.pageSize),el=document.getElementById('page-select');
    if(el)el.indeterminate=pageVars.some(v=>state.plan[v.id])&&!pageVars.every(v=>state.plan[v.id]);
  }
  if(focusSelector){const next=app.querySelector(focusSelector);next?.focus({preventScroll:true});if(next&&typeof selectionStart==='number'&&['text','search','textarea'].includes(next.type)){try{next.setSelectionRange(selectionStart,selectionEnd);}catch{}}}
}
function addVariables(vars,label='Variables'){
  let added=0;
  for(const v of vars){if(!state.plan[v.id]){state.plan[v.id]=blankEntry(state.context.mode);added++;}}
  save();render();if(detailDialog.open)renderDetail();
  toast(added?`${added} variable${added===1?'':'s'} added to your plan.`:`${label} already in your plan.`);
}
function bulkAdd(vars,label){const fresh=vars.filter(v=>!state.plan[v.id]);if(fresh.length>25){confirmModal(`Add ${fresh.length} variables?`,`${label}. These will be added without removing your existing selections. Source review flags remain attached.`,()=>addVariables(fresh),'Add variables');}else addVariables(fresh,label);}
function toggleVariable(id){if(!byId.has(id)||isRequiredVariable(byId.get(id)))return;if(state.plan[id])delete state.plan[id];else state.plan[id]=blankEntry(state.context.mode);save();render({preserveFocus:true});if(detailDialog.open)renderDetail();}
function detailOverview(v){const reasons=scopeReasons(v,state.context),e=state.plan[v.id];return `<h3>Unit / reporting format</h3><div class="unit-box"><div class="label">Workbook-provided value</div><strong class="mono">${esc(v.units.display)}</strong><div class="raw-unit">Source literal: ${esc(v.units.raw||'(blank)')} · no conversion applied</div></div>${v.units.status!=='provided'?`<div class="unit-warning">The source does not specify a usable unit or reporting format. Define the quantity and reporting basis before choosing a unit. Your plan can record a separate researcher-entered format below.</div>`:''}${v.units.notes.map(n=>`<div class="unit-warning">${esc(n)}</div>`).join('')}
    <h3>Why this variable is here</h3><p>${reasons.length?esc(reasons.join(' · ')):'Available in the full source library. It may lie outside your current study filters.'}${v.foundation?' The starter label is an editorial suggestion, not a new classification.':''}</p>${v.condition?`<p class="methodology-hint">Configuration relevance: ${v.condition==='tracking'?'tracking-related field':'cell-level module geometry; relevance is user-controlled'}.</p>`:''}
    <div class="detail-section"><h3>Source session coverage</h3><div class="session-tags">${v.sessions.map(s=>`<span class="session-tag">${esc(s)}</span>`).join('')}</div><p class="methodology-hint">Session coverage is provenance, not a statement of exclusive crop applicability.</p></div>
    <div class="detail-section"><h3>Your measurement details</h3>${e?`<p class="methodology-hint">Saved only in your plan. These entries do not change the source matrix.</p><div class="detail-input-grid"><label class="field full">Reporting unit / format<input id="entry-unit" data-entry="unitOverride" maxlength="300" value="${esc(e.unitOverride)}" placeholder="${esc(v.units.status==='provided'?`Use source: ${v.units.raw}`:'Enter the agreed unit or categorical format')}"><small>A filled value is explicitly exported as researcher-entered.</small></label><label class="field">Sampling interval / schedule<input id="entry-schedule" data-entry="schedule" maxlength="4000" value="${esc(e.schedule)}" placeholder="e.g. interval, season, harvest stage"></label><label class="field">Position / height / depth<input id="entry-position" data-entry="position" maxlength="4000" value="${esc(e.position)}" placeholder="Record location and reference treatment"></label><label class="field full">Method / instrument<input id="entry-method" data-entry="method" maxlength="4000" value="${esc(e.method)}" placeholder="Method, instrument, calibration, or protocol identifier"></label><label class="field full">Notes / rationale<textarea id="entry-notes" data-entry="notes" maxlength="4000" rows="3" placeholder="Replication, aggregation period, uncertainty, or applicability notes">${esc(e.notes)}</textarea></label></div><p class="methodology-hint">${icon('check')} Changes save as you type.</p>`:`<div class="resource-empty">Add this variable to your plan to enter a reporting format, sampling schedule, location, and method.</div>`}</div>
    <div class="source-meta"><strong>Source record</strong><br>${esc(v.source.sheet)} · row ${v.source.row}<br>Original subcategory: ${esc(v.sourceSubcategory)}<br>${esc(v.source.rows)}</div>`;}
function detailVotes(v){
  const c=v.consensus,segments=[...Object.entries(c.counts),['?',c.unresolved]];
  const grouped={};for(const cell of v.voteCells){const session=expertById.get(cell.expertSessionId)?.session||'Unknown session';(grouped[session]??=[]).push(cell);}
  return `<h3>Expert-vote result</h3><div class="evidence-head"><strong>${pct(c.agreement)}</strong><span>${c.majorityCode?`${c.counts[c.majorityCode]} of ${c.denominator} non-NA cells support ${c.majorityCode}`:STATUS_NAMES[c.status]}</span></div><p>${esc(c.status==='legacy-core'?'The majority selected C. A descriptive or universal subtype cannot be inferred from that code.':c.status==='tie'?'Two categories each meet 50%. Neither is assigned.':c.status==='no-votes'?'All expert-session cells are NA. No classification is assigned.':c.status==='no-consensus'?'No single recognized category reaches 50% of all non-NA cells.':`A unique ${c.category} vote meets the inclusive 50% threshold.`)}</p>
      ${c.limitedEvidence?`<div class="unit-warning">Limited evidence: this result is based on ${c.denominator} non-NA cell${c.denominator===1?'':'s'}. A high percentage does not imply a large expert panel.</div>`:''}
      <div class="vote-stack" role="img" aria-label="${esc(segments.map(([code,n])=>`${code==='?'?'Unresolved':code}: ${n}`).join('; '))}">${segments.filter(([,n])=>n).map(([code,n])=>`<span class="${code==='?'?'unknown':code.toLowerCase()}" style="width:${c.denominator?n/c.denominator*100:0}%" title="${code}: ${n}"></span>`).join('')}</div>
      <table class="votes-table"><thead><tr><th>Source code</th><th>Cells</th><th>Share</th></tr></thead><tbody>${segments.map(([code,n])=>`<tr><td><span class="vote-legend ${code.toLowerCase()}"></span>${code==='?'?'Unresolved / mixed indications':code==='C'?'C · legacy core':`${code} · ${TIERS[code].short}`}</td><td>${n}</td><td>${c.denominator?pct(n/c.denominator):'—'}</td></tr>`).join('')}<tr><td>NA / blank · excluded</td><td>${c.na}</td><td>—</td></tr></tbody></table>
      <p class="evidence-note">Denominator: <strong>${c.denominator}</strong> non-NA expert-session cells, of which ${c.recognized} are interpretable single-code votes and ${c.unresolved} remain unresolved. Mixed and unknown indications stay in the denominator but do not support a category. Expert sessions may include the same individual more than once.</p>
      <div class="detail-section"><h3>Original indications by session</h3><p class="methodology-hint">Anonymous column IDs preserve each non-NA cell. Open a session to inspect the original literals.</p>${Object.entries(grouped).map(([session,cells])=>`<details class="raw-session"><summary>${esc(session)} <span class="muted">· ${cells.length} cells</span></summary><div class="raw-cells">${cells.map(cell=>`${esc(cell.expertSessionId)} <code>${esc(cell.raw)}</code>${normalizeVote(cell.raw)==='?'?' <span>unresolved</span>':''}`).join('<br>')}</div></details>`).join('')||'<div class="resource-empty">No non-NA indications recorded.</div>'}</div>`;
}
function detailResources(v){return `<h3>Imported methodology notes</h3><p class="methodology-hint">Verbatim workbook content, consolidated across source records. These notes have not been independently checked or converted into a protocol.</p>${v.notes?`<div class="source-notes">${esc(v.notes.replaceAll(' || ','\n\n'))}</div>`:'<div class="resource-empty">No methodology notes were recorded for this variable.</div>'}<div class="detail-section"><h3>Reviewed methods</h3>${v.methods.length?v.methods.map(m=>`<article class="resource-card"><strong>${esc(m.title)}</strong><p>${esc(m.summary||'')}</p><p class="methodology-hint">Reviewed by ${esc(m.reviewer||'not recorded')} · ${esc(m.reviewedOn||'date not recorded')}</p>${safeURL(m.url)?`<a href="${esc(safeURL(m.url))}" target="_blank" rel="noopener noreferrer">View method ${icon('external')}</a>`:''}</article>`).join(''):'<div class="resource-empty">No reviewed method linked yet. This record is ready for protocols, instrument guidance, and sampling examples.</div>'}</div><div class="detail-section"><h3>Publications & examples</h3>${v.publications.length?v.publications.map(p=>`<article class="resource-card">${safeURL(p.url)?`<a href="${esc(safeURL(p.url))}" target="_blank" rel="noopener noreferrer">${esc(p.title)} ${icon('external')}</a>`:`<strong>${esc(p.title)}</strong>`}<p>${esc(p.citation||'')}</p><p class="methodology-hint">Reviewed by ${esc(p.reviewer||'not recorded')} · ${esc(p.reviewedOn||'date not recorded')}</p></article>`).join(''):'<div class="resource-empty">No reviewed publications linked yet. Existing references inside source notes are not presented as verified citations.</div>'}<button class="btn btn-soft btn-sm" data-action="feedback-variable" data-id="${v.id}">${icon('plus')}Suggest a method or publication</button></div>`;}
function openDetail(id,tab='overview'){if(!byId.has(id))return;detailId=id;detailTab=['overview','votes','resources'].includes(tab)?tab:'overview';renderDetail();if(!detailDialog.open)detailDialog.showModal();detailDialog.scrollTop=0;}
function renderDetail(){const v=byId.get(detailId);if(!v)return;detailDialog.innerHTML=`<div class="detail-top"><button class="icon-button detail-close" data-action="close-detail" aria-label="Close variable details">${icon('close')}</button><div class="detail-id mono">${esc(v.id)} · SOURCE ROW ${v.source.row}</div><h2 id="detail-title">${esc(v.name)}</h2><p class="detail-subtitle">${esc(labelCategory(v.category))} / ${esc(v.subcategory)}</p><div class="detail-badges">${badge(v)}${v.consensus.limitedEvidence?'<span class="badge neutral">Limited evidence</span>':''}${v.foundation?'<span class="badge neutral">Starter suggestion</span>':''}</div></div><div class="detail-tabs" role="tablist" aria-label="Variable information">${[['overview','Overview'],['votes','Expert votes'],['resources','Methods & sources']].map(([id,label])=>`<button id="tab-${id}" role="tab" aria-selected="${detailTab===id}" aria-controls="detail-panel" tabindex="${detailTab===id?'0':'-1'}" class="detail-tab${detailTab===id?' active':''}" data-action="detail-tab" data-tab="${id}">${label}</button>`).join('')}</div><div id="detail-panel" class="detail-content" role="tabpanel" aria-labelledby="tab-${detailTab}" tabindex="0">${detailTab==='overview'?detailOverview(v):detailTab==='votes'?detailVotes(v):detailResources(v)}</div><div class="detail-actions"><button class="btn btn-quiet" data-action="feedback-variable" data-id="${v.id}">${icon('chat')}Suggest a correction</button><button class="btn ${state.plan[v.id]?'btn-soft':'btn-primary'}" data-action="toggle-variable" data-id="${v.id}"${isRequiredVariable(v)?' disabled':''}>${icon(state.plan[v.id]?'check':'plus')}${isRequiredVariable(v)?'Required metadata':state.plan[v.id]?'In your plan · remove':'Add to my plan'}</button></div>`;}
function openUtility(content){utilityDialog.innerHTML=`<div class="utility-content"><button class="icon-button close-utility" data-action="close-utility" aria-label="Close dialog">${icon('close')}</button>${content}</div>`;if(!utilityDialog.open)utilityDialog.showModal();}
function confirmModal(title,description,onConfirm,label='Continue'){confirmAction=onConfirm;openUtility(`<h2 id="utility-title">${esc(title)}</h2><p>${esc(description)}</p><div class="utility-actions"><button class="btn" data-action="close-utility">Cancel</button><button class="btn btn-primary" data-action="confirm">${esc(label)}</button></div>`);}
function repositoryURL(){const configured=safeURL(window.AIS_CONFIG?.repositoryUrl);if(configured&&/^https:\/\/github\.com\/[^/]+\/[^/]+\/?$/.test(configured))return configured.replace(/\/$/,'');if(location.hostname.endsWith('.github.io')){const owner=location.hostname.slice(0,-10),repo=location.pathname.split('/').filter(Boolean)[0];if(/^[A-Za-z0-9_.-]+$/.test(owner))return `https://github.com/${owner}/${repo&&!repo.includes('.')?repo:`${owner}.github.io`}`;}return null;}
function feedbackModal(id=null){feedbackVariable=byId.get(id)||null;const repo=repositoryURL();openUtility(`<h2 id="utility-title">Help improve the framework.</h2><p>${feedbackVariable?`Suggest a change for <strong>${esc(feedbackVariable.name)}</strong>.`:'Report an issue, suggest a variable, or share feedback on the workflow.'}</p><form id="feedback-form"><label class="field">Feedback type<select id="feedback-type"><option>Classification</option><option>Units / reporting format</option><option>Method / publication</option><option>Variable definition</option><option>App experience</option><option>Other</option></select></label><label class="field">Your suggestion<textarea id="feedback-text" maxlength="8000" rows="5" required placeholder="Describe the change and include a source, where available."></textarea></label><p class="feedback-hint">${repo?'Opens a draft GitHub issue. Review and submit it on GitHub; nothing is sent automatically.':'No destination repository has been configured yet. Download your feedback as a Markdown file; it is not submitted automatically.'} Do not include private study data.</p><div class="utility-actions"><button type="button" class="btn" data-action="close-utility">Cancel</button><button type="submit" class="btn btn-primary">${icon(repo?'external':'download')}${repo?'Open draft issue':'Download feedback'}</button></div></form>`);}
function fileSlug(){return (state.study.name||'agrivoltaics-standards-plan').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||'agrivoltaics-standards-plan';}
function downloadFile(text,name,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){downloadFile(toCSV(planRows(DATA.variables,state.plan,state.study,DATA)),`${fileSlug()}.csv`,'text/csv;charset=utf-8');toast('Measurement plan exported. Source values and review flags are included.');}
function feedbackText(){const v=feedbackVariable;return `## Feedback type\n${document.getElementById('feedback-type').value}\n\n## Variable\n${v?`${v.name}\nID: ${v.id}\nSource: ${v.source.sheet}, row ${v.source.row}`:'General feedback'}\n\n## Suggestion\n${document.getElementById('feedback-text').value}\n\n## Dataset\n${DATA.datasetVersion}\nPolicy: ${DATA.policyVersion}\n`;}
function afterContextChange(){state.page=1;save();render({preserveFocus:true});}

// Event delegation keeps source content inert: no source text becomes executable markup.
document.addEventListener('click',event=>{
  const target=event.target.closest('[data-action]');if(!target||target.disabled)return;
  const action=target.dataset.action,id=target.dataset.id;
  switch(action){
    case 'view':setView(target.dataset.view);break;
    case 'step':{const step=Number(target.dataset.step);setView(['setup','library','plan'][step]);break;}
    case 'topic':state.context.topics=state.context.topics.includes(id)?state.context.topics.filter(x=>x!==id):[...state.context.topics,id];afterContextChange();break;
    case 'crop':{const g=target.dataset.group;state.context.cropGroups=state.context.cropGroups.includes(g)?state.context.cropGroups.filter(x=>x!==g):[...state.context.cropGroups,g];afterContextChange();break;}
    case 'mode':state.context.mode=target.dataset.mode;afterContextChange();break;
    case 'continue':{state.filters={query:'',category:'',subcategory:'',tier:'',units:'',evidence:''};state.page=1;setView('library',{all:false});}break;
    case 'scope':state.allLibrary=target.dataset.scope==='all';state.page=1;state.filters.category='';state.filters.subcategory='';render();break;
    case 'category':state.filters.category=target.dataset.category;state.filters.subcategory='';state.page=1;render();break;
    case 'tier':state.filters.tier=state.filters.tier===target.dataset.tier?'':target.dataset.tier;state.page=1;render();break;
    case 'clear-filter':state.filters[target.dataset.filter]='';state.page=1;render();break;
    case 'reset-filters':state.filters={query:'',category:'',subcategory:'',tier:'',units:'',evidence:''};state.page=1;render();break;
    case 'mobile-filters':state.mobileFilters=!state.mobileFilters;render();break;
    case 'page':state.page+=Number(target.dataset.delta);render();document.querySelector('.result-bar')?.scrollIntoView({block:'center',behavior:'instant'});break;
    case 'toggle-variable':toggleVariable(id);break;
    case 'remove-variable':if(isRequiredVariable(byId.get(id)))break;delete state.plan[id];save();render();toast('Variable removed from this plan.');break;
    case 'select-page':{const pageVars=visibleLibrary().slice((state.page-1)*state.pageSize,state.page*state.pageSize);if(pageVars.every(v=>state.plan[v.id])){for(const v of pageVars)if(!isRequiredVariable(v))delete state.plan[v.id];save();render();toast('Optional variables on this page removed; required metadata retained.');}else addVariables(pageVars);break;}
    case 'add-filtered':bulkAdd(visibleLibrary(),'All variables matching your current filters');break;
    case 'add-core':{const vars=libraryScope().filter(v=>['CD','CU'].includes(v.consensus.category));bulkAdd(vars,'All exact CD / CU classifications in the current study or library scope; other filters are not applied');break;}
    case 'add-missing-core':bulkAdd(missingCore(),'All currently missing expert-voted CD / CU variables');break;
    case 'add-foundation':bulkAdd(DATA.variables.filter(v=>foundationMatches(v,state.context)),'The editorial starter checklist for your study context; this does not alter classifications');break;
    case 'detail':openDetail(id,target.dataset.tab||'overview');break;
    case 'close-detail':detailDialog.close();if(state.view==='plan')render();break;
    case 'detail-tab':detailTab=target.dataset.tab;renderDetail();document.getElementById(`tab-${detailTab}`)?.focus({preventScroll:true});break;
    case 'feedback':feedbackModal();break;
    case 'feedback-variable':feedbackModal(id);break;
    case 'close-utility':utilityDialog.close();confirmAction=null;break;
    case 'confirm':{const fn=confirmAction;confirmAction=null;utilityDialog.close();fn?.();break;}
    case 'privacy':openUtility('<h2 id="utility-title">Your plan stays with you.</h2><p>The app runs in your browser. There is no account, database, analytics script, or server upload. Study notes and selections are stored in this browser’s local storage, which is not encrypted by the application.</p><p style="margin-top:14px">Exported files contain the study details you entered. Share them deliberately. GitHub Pages or another host may maintain ordinary access logs. Feedback opens a draft issue only when you request it; GitHub issues may be public.</p><p style="margin-top:14px">To remove your saved data, clear selected variables and study details, or clear site storage in your browser.</p><div class="utility-actions"><button class="btn btn-danger" data-action="erase-storage">Erase all local study data</button><button class="btn" data-action="close-utility">Close</button></div>');break;
    case 'erase-storage':confirmModal('Erase this saved study?','This removes the study name, notes, selections, and settings from this browser. Export JSON first to keep a copy.',()=>{try{localStorage.removeItem(storeKey);localStorage.removeItem(storeKey+':recovery');localStorage.removeItem(storeKey+':probe');}catch{}state.context=structuredClone(DEFAULT_CONTEXT);state.study={name:'',notes:''};state.plan=defaultPlan(DATA.variables);hasSavedStudy=false;setView('setup');toast('Local study data erased.');},'Erase local study');break;
    case 'clear-plan':confirmModal('Clear optional variables?','Required site and PV metadata and their notes remain. Optional variables (including removable CD/CU defaults) will be removed. Export JSON first to keep a copy.',()=>{state.plan=Object.fromEntries(Object.entries(state.plan).filter(([id])=>isRequiredVariable(byId.get(id))));save();render();toast('Optional variables cleared; required metadata retained.');},'Clear variables');break;
    case 'import':document.getElementById('plan-file').click();break;
    case 'export-csv':exportCSV();break;
    case 'export-json':downloadFile(JSON.stringify(exportPlan(state,DATA),null,2),`${fileSlug()}.json`,'application/json');toast('Reusable plan saved as JSON.');break;
    case 'export-template':downloadFile(toCSV(measurementRows(DATA.variables,state.plan,state.study)),`${fileSlug()}-observations.csv`,'text/csv;charset=utf-8');toast('Blank observation template exported.');break;
    case 'export-audit':downloadFile(toCSV(auditRows(DATA.variables)),'agrivoltaics-standards-classification-audit-v15.csv','text/csv;charset=utf-8');break;
    case 'export-data':downloadFile(JSON.stringify(DATA,null,2),'agrivoltaics-standards-source-data-v15.json','application/json');break;
    case 'print':window.print();break;
  }
});
document.addEventListener('input',event=>{
  const el=event.target;
  if(el.id==='variable-search'){state.filters.query=el.value;state.page=1;render({preserveFocus:true});document.getElementById('sr-status').textContent=`${visibleLibrary().length} matching variables.`;}
  if(el.dataset.study){state.study[el.dataset.study]=el.value;save();}
  if(el.dataset.entry&&detailId&&state.plan[detailId]){state.plan[detailId][el.dataset.entry]=el.value;save();}
});
document.addEventListener('change',event=>{
  const el=event.target;
  if(el.dataset.context){state.context[el.dataset.context]=el.type==='checkbox'?el.checked:el.value;afterContextChange();}
  if(el.dataset.filter){state.filters[el.dataset.filter]=el.value;state.page=1;render({preserveFocus:true});}
  if(el.id==='sort-select'){state.sort=el.value;state.page=1;render({preserveFocus:true});}
  if(el.id==='page-size'){state.pageSize=Number(el.value);state.page=1;render({preserveFocus:true});}
  if(el.id==='plan-grouping'){state.planGrouping=el.value;render({preserveFocus:true});}
  if(el.dataset.planStatus&&state.plan[el.dataset.planStatus]){state.plan[el.dataset.planStatus].status=el.value;save();}
});
document.addEventListener('submit',event=>{if(event.target.id!=='feedback-form')return;event.preventDefault();const text=feedbackText(),repo=repositoryURL(),kind=document.getElementById('feedback-type').value,title=`[${kind}] ${feedbackVariable?.name||'Research planner feedback'}`;
  if(repo){const u=new URL(`${repo}/issues/new`);u.searchParams.set('title',title);u.searchParams.set('body',text);window.open(u.href,'_blank','noopener,noreferrer');toast('GitHub issue draft opened. Review and submit it there.');}
  else{downloadFile(text,`agrivoltaics-standards-feedback${feedbackVariable?'-'+feedbackVariable.id:''}.md`,'text/markdown;charset=utf-8');toast('Feedback file prepared. It has not been submitted.');}
  utilityDialog.close();
});
document.getElementById('plan-file').addEventListener('change',async event=>{const input=event.target,file=input.files[0];input.value='';if(!file)return;try{if(file.size>5_000_000)throw new Error('Plan file exceeds the 5 MB limit.');const candidate=validatePlan(JSON.parse(await file.text()),DATA);pendingImport=candidate;confirmModal(`Import ${Object.keys(candidate.plan).length} variables?`,'This replaces the current study and selected variables. Existing changes are not merged. Export the current plan first to keep a copy.',()=>{state.study=pendingImport.study;state.context=pendingImport.context;state.plan=pendingImport.plan;const warning=pendingImport.warning;pendingImport=null;save();setView('plan');toast(warning||'Plan imported successfully.',Boolean(warning));},'Replace & import');}catch(error){toast(`Import stopped: ${error.message}`,true);}});
document.addEventListener('keydown',event=>{
  const inputFocused=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName)||document.activeElement?.isContentEditable;
  if(event.key==='/'&&!inputFocused&&!detailDialog.open&&!utilityDialog.open&&state.view==='library'){event.preventDefault();document.getElementById('variable-search')?.focus();}
  if(event.target.matches?.('.detail-tab')&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=['overview','votes','resources'],i=tabs.indexOf(detailTab);detailTab=event.key==='Home'?tabs[0]:event.key==='End'?tabs[2]:tabs[(i+(event.key==='ArrowRight'?1:2))%3];renderDetail();document.getElementById(`tab-${detailTab}`)?.focus();}
});
for(const dialog of [detailDialog,utilityDialog])dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();});
detailDialog.addEventListener('close',()=>{if(DATA)render();});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(['setup','library','plan','guide'].includes(view))setView(view);});

async function init(){
  document.title=PROJECT_NAME;
  try{
    if(window.AV_DATA)DATA=window.AV_DATA;
    else{const response=await fetch(new URL('../data/variables.json',import.meta.url));if(!response.ok)throw new Error(`Dataset request failed (${response.status}).`);DATA=await response.json();}
    if(DATA.schemaVersion!=='1.0.0'||!Array.isArray(DATA.variables)||!DATA.variables.length)throw new Error('Unsupported or empty dataset.');
    byId=new Map(DATA.variables.map(v=>[v.id,v]));expertById=new Map(DATA.expertSessions.map(e=>[e.id,e]));
    storeKey='agrifield:plan:v1:'+location.pathname.replace(/\/[^/]*\.html$/,'/');
    let warning='',cached=null;
    try{cached=localStorage.getItem(storeKey);}catch{storageAvailable=false;}
    state.plan=defaultPlan(DATA.variables);
    if(cached){
      try{const validated=validatePlan(JSON.parse(cached),DATA);state.study=validated.study;state.context=validated.context;state.plan=validated.plan;hasSavedStudy=true;warning=validated.warning;}
      catch(error){warning='Saved study data could not be restored. A recovery copy is retained where storage is available; import a saved JSON plan to recover it.';try{localStorage.setItem(storeKey+':recovery',cached);}catch{storageAvailable=false;}}
    }
    // Probe storage without marking a new empty study as a saved plan.
    try{localStorage.setItem(storeKey+':probe','1');localStorage.removeItem(storeKey+':probe');}catch{storageAvailable=false;}
    const route=location.hash.slice(1);if(['setup','library','plan','guide'].includes(route))state.view=route;
    if(state.view==='library'&&!state.context.topics.length)state.allLibrary=true;
    render();if(warning)toast(warning,true);
  }catch(error){app.innerHTML=`<main class="loading"><img src="${esc(LOGO_URL)}" alt="" width="48" height="48"><h1>Unable to load the library.</h1><p>${esc(error.message)}</p><p class="small">Run the repository through a local web server, or open the standalone demo. Check that data/variables.json is present.</p><button class="btn" onclick="location.reload()">Try again</button></main>`;console.error(error);}
}
init();
